import{_ as e,c as i,o as l,a2 as r}from"./chunks/framework.gSKzFT2J.js";const m=JSON.parse('{"title":"Git & GitHub : Pratique","description":"","frontmatter":{},"headers":[],"relativePath":"fr/pratique/exercices.md","filePath":"fr/pratique/exercices.md"}'),o={name:"fr/pratique/exercices.md"},t=r('<h1 id="git-github-pratique" tabindex="-1">Git &amp; GitHub : Pratique <a class="header-anchor" href="#git-github-pratique" aria-label="Permalink to &quot;Git &amp; GitHub : Pratique&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>Git et GitHub sont des outils essentiels pour la gestion de versions et la collaboration dans le développement logiciel. Ce workshop se concentre sur la gestion des workflows avec Git et GitHub dans le cadre d&#39;un projet agile, avec un accent particulier sur la méthodologie Scrum et la livraison des scénarios dans les délais impartis.</p><h2 id="objectifs" tabindex="-1">Objectifs <a class="header-anchor" href="#objectifs" aria-label="Permalink to &quot;Objectifs&quot;">​</a></h2><ul><li>Planifier les tâches en suivant la méthodologie Scrum.</li><li>Finaliser les scénarios dans les délais prévus.</li><li>Rédiger un rapport d&#39;activités de groupe détaillé.</li><li>Maîtriser les commandes Git essentielles.</li><li>Explorer la plateforme GitHub pour la gestion des versions.</li><li>Gérer le temps, le stress, et garantir la livraison des livrables.</li><li>Participer aux réunions de fin de scénario.</li><li>Formaliser les processus de travail pour améliorer l&#39;efficacité.</li></ul><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte&quot;">​</a></h2><ul><li>Se familiariser avec les commandes Git de base.</li><li>Gérer le workflow Git dans un environnement collaboratif.</li><li>Maîtriser le workflow Git/GitHub pour un développement fluide.</li></ul><h2 id="livrables" tabindex="-1">Livrables <a class="header-anchor" href="#livrables" aria-label="Permalink to &quot;Livrables&quot;">​</a></h2><ol><li>Un rapport d&#39;activités détaillant les tâches effectuées.</li><li>Une planification des scénarios sous forme de Product Backlog.</li><li>Un livrable respectant les délais définis.</li></ol><h2 id="prerequis" tabindex="-1">Prérequis <a class="header-anchor" href="#prerequis" aria-label="Permalink to &quot;Prérequis&quot;">​</a></h2><ul><li>Git Bash</li><li>Compte GitHub</li><li>Tableau Trello pour la gestion des tâches</li><li>Éditeur de texte VSCode</li><li>P4Merge (outil pour la comparaison des fichiers)</li></ul><h2 id="mots-cles" tabindex="-1">Mots Clés <a class="header-anchor" href="#mots-cles" aria-label="Permalink to &quot;Mots Clés&quot;">​</a></h2><ul><li><code>git ls-files</code></li><li><code>git config --global --list</code></li><li><code>git log --oneline --graph --decorate --all</code></li><li><code>git checkout -b &quot;nom_branche&quot;</code></li><li><code>ssh-keygen -t rsa -C &#39;email&#39;</code></li></ul><h2 id="liens-utiles" tabindex="-1">Liens Utiles <a class="header-anchor" href="#liens-utiles" aria-label="Permalink to &quot;Liens Utiles&quot;">​</a></h2><ul><li><a href="https://www.perforce.com" target="_blank" rel="noreferrer">Diff Tools and Helix Merge (P4Merge) | Perforce</a></li><li><a href="https://stackoverflow.com" target="_blank" rel="noreferrer">Stack Overflow</a> – Apprenez, partagez, et développez vos compétences.</li><li><a href="https://initializr.com" target="_blank" rel="noreferrer">Initializr - Démarrez un projet HTML5 en 15 secondes !</a></li><li><a href="https://github.com" target="_blank" rel="noreferrer">Configurer P4Merge comme outil de fusion sous Windows</a></li><li><a href="https://gitexplorer.com" target="_blank" rel="noreferrer">Git Explorer</a></li><li><a href="https://github.com" target="_blank" rel="noreferrer">P4Merge et Git Extensions sur GitHub</a></li></ul><h2 id="scenarios" tabindex="-1">Scénarios <a class="header-anchor" href="#scenarios" aria-label="Permalink to &quot;Scénarios&quot;">​</a></h2><h3 id="scenario-1" tabindex="-1">Scénario #1 <a class="header-anchor" href="#scenario-1" aria-label="Permalink to &quot;Scénario #1&quot;">​</a></h3><h4 id="preface" tabindex="-1">Préface <a class="header-anchor" href="#preface" aria-label="Permalink to &quot;Préface&quot;">​</a></h4><ul><li>Le Product Backlog est déjà priorisé. L&#39;objectif est de maintenir les tâches au sein du groupe et de respecter les délais de livraison.</li><li>Un rapport d&#39;activités sous forme de mind mapping est exigé.</li><li>Utilisez Git Bash et les commandes pour ce scénario.</li></ul><h4 id="product-backlog" tabindex="-1">Product Backlog <a class="header-anchor" href="#product-backlog" aria-label="Permalink to &quot;Product Backlog&quot;">​</a></h4><ol><li><p><strong>First step: Immersion</strong></p><ul><li>Définir Git en quelques mots.</li><li>Expliquer le fonctionnement du fichier caché <code>.git</code>.</li><li>Créer un répertoire nommé <code>/projects</code> sur le bureau.</li><li>Créer un repository local nommé <code>/demo</code>.</li><li>Expliquer l&#39;utilité des commentaires dans Git.</li><li>Créer un fichier <code>README.md</code> et y ajouter la ligne <code># Demo project un simple fichier</code>.</li><li>Faire le staging et le commit avec un commentaire approprié.</li></ul></li><li><p><strong>Second step: Découverte</strong></p><ul><li>Explorer les fichiers de configuration <code>.git</code>.</li><li>Taper <code>ls -al</code> pour afficher les fichiers cachés.</li><li>Expliquer les termes suivants : HEAD, LOGS, BRANCHES.</li><li>Créer un fichier <code>Licence.md</code> dans le repository et faire un commit.</li><li>Afficher les fichiers traqués par Git.</li></ul></li><li><p><strong>Third step: Historique</strong></p><ul><li>Afficher le dernier commit sur une seule ligne en ajoutant l&#39;option pour visualiser la hiérarchie des branches.</li><li>Créer un alias pour cette commande sous le nom <code>historique</code>.</li><li>Afficher la liste des alias définis dans Git.</li><li>Afficher l&#39;historique des commits du fichier <code>README.md</code> en utilisant l&#39;alias créé.</li></ul></li><li><p><strong>Fourth step: Exclusion des fichiers</strong></p><ul><li>Renommer le fichier <code>Licence.md</code> en <code>Licence.txt</code>.</li><li>Faire le staging sans utiliser <code>git add .</code>.</li><li>Créer un fichier <code>application.log</code> et l&#39;ignorer.</li><li>Créer un fichier <code>.gitignore</code> et y ajouter <code>*.log</code> pour ignorer les fichiers log.</li><li>Faire le staging et le commit, puis observer le comportement de Git.</li></ul></li><li><p><strong>Fifth step: Branching and Merging</strong></p><ul><li>Modifier le fichier <code>README.md</code> sans faire de commit.</li><li>Créer une branche <code>updates</code>, faire le staging et le commit en une seule ligne.</li><li>Afficher l&#39;historique des commits avec l&#39;alias créé.</li><li>Revenir à la branche <code>master</code>.</li><li>Effectuer un merge de la branche <code>updates</code>.</li></ul></li><li><p><strong>Sixth step: Résolution de conflits</strong></p><ul><li>Créer une branche <code>BAD</code>.</li><li>Modifier le fichier <code>README.md</code> et ajouter <code>Trouble</code>.</li><li>Faire le staging et le commit en une seule ligne.</li><li>Basculer sur la branche <code>master</code> et modifier le fichier <code>README.md</code> pour ajouter <code>Troubleshooting</code>.</li><li>Résoudre les conflits lors du merge et analyser les messages reçus.</li></ul></li><li><p><strong>Seventh step: Outils de fusion</strong></p><ul><li>Installer P4Merge.</li><li>Configurer P4Merge comme outil de fusion avec <code>git config --global</code>.</li><li>Utiliser <code>git mergetool</code> pour analyser les conflits.</li></ul></li><li><p><strong>Eighth step: Challenge</strong></p><ul><li>Rédiger des clauses dans <code>.gitignore</code> pour exclure les fichiers indésirables et redondants.</li><li>Ne conserver que les fichiers <code>licence.txt</code>, <code>README.md</code>, et <code>.gitignore</code>.</li></ul></li></ol><h3 id="scenario-2" tabindex="-1">Scénario #2 <a class="header-anchor" href="#scenario-2" aria-label="Permalink to &quot;Scénario #2&quot;">​</a></h3><h4 id="preface-1" tabindex="-1">Préface <a class="header-anchor" href="#preface-1" aria-label="Permalink to &quot;Préface&quot;">​</a></h4><p>Vous avez terminé la phase #1 et êtes prêts à aborder des concepts plus avancés. Le Product Backlog est déjà priorisé.</p><h4 id="product-backlog-1" tabindex="-1">Product Backlog <a class="header-anchor" href="#product-backlog-1" aria-label="Permalink to &quot;Product Backlog&quot;">​</a></h4><ol><li><p><strong>First step: Tagging</strong></p><ul><li>Se déplacer sur la branche principale.</li><li>Créer un tag <code>V1.0</code> avec le commentaire <code>RELEASE 1.0</code>.</li><li>Afficher les informations sur le tag.</li><li>Discuter de l&#39;utilité des tags dans un workflow Git.</li></ul></li><li><p><strong>Second step: Stashing et sauvegarde du travail en cours</strong></p><ul><li>Modifier le fichier <code>README.md</code> et ajouter une ligne.</li><li>Mettre la tâche en pause avec <code>git stash</code>.</li><li>Expliquer le fonctionnement de <code>git stash</code>.</li><li>Utiliser <code>git stash list</code> et <code>git status</code>.</li><li>Ajouter <code>APACHE 2.0</code> à <code>Licence.txt</code>, faire le staging et le commit en une seule ligne.</li><li>Exécuter <code>git stash pop</code> pour récupérer les modifications stachées.</li></ul></li><li><p><strong>Third step: Voyage sur GitHub</strong></p><ul><li>Créer un compte GitHub.</li><li>Créer un repository GitHub public sans ajouter <code>README.md</code>.</li><li>Configurer un remote en HTTPS et pousser les changements avec <code>git push -u origin master --tags</code>.</li><li>Expliquer les options <code>-u</code> et <code>--tags</code>.</li></ul></li><li><p><strong>Fourth step: Mini challenge (optionnel)</strong></p><ul><li>Créer une authentification SSH entre votre repo local et GitHub.</li></ul></li><li><p><strong>Fifth step: Création d&#39;une copie locale</strong></p><ul><li>Créer un repository <code>Monsiteweb</code> sur GitHub avec <code>.gitignore</code> et <code>licence.txt</code>.</li><li>Cloner le repository sur votre machine locale et vérifier le clone.</li></ul></li><li><p><strong>Sixth step: Envoi du site web</strong></p><ul><li>Télécharger un site web depuis Initializr.</li><li>Copier le site téléchargé dans le repository local.</li><li>Faire le staging et le commit en une seule ligne.</li><li>Pousser les changements à GitHub.</li></ul></li><li><p><strong>Seventh step: Fetch et Pull</strong></p><ul><li>Modifier <code>Index.html</code> sur GitHub et faire un commit.</li><li>Modifier <code>README.md</code> localement et effectuer un commit en une seule ligne.</li><li>Exécuter les commandes <code>git fetch</code>, <code>git status</code>, <code>git pull</code>, et <code>git push</code>.</li><li>Vérifier les commits sur GitHub.</li></ul></li></ol>',26),a=[t];function s(c,n,d,u,p,h){return l(),i("div",null,a)}const f=e(o,[["render",s]]);export{m as __pageData,f as default};
